    <section class="guide-panel" id="{{$module['id']}}" data-search="{{$module['title']}} {{$module['purpose']}} {{$module['where']}} {{$module['who']}} @foreach($module['rules'] as $rule) {{$rule[0]}} {{$rule[1]}} @endforeach">
      <header class="guide-panel-heading"><span class="guide-panel-count">თემა {{str_pad((string)($loop->iteration + 1), 2, '0', STR_PAD_LEFT)}}</span><h2>{{preg_replace('/^\d+\.\s*/u', '', $module['title'])}}</h2><p>{{$module['purpose']}}</p></header>
      <div class="guide-facts"><div><strong>სად ვიპოვოთ</strong>{{$module['where']}}</div><div><strong>ვის აქვს წვდომა</strong>{{$module['who']}}</div></div>
      @foreach($module['rules'] as $rule)<div class="guide-entry {{($rule[2] ?? null) === 'warning' ? 'is-warning' : ''}}"><h3>{{$rule[0]}}</h3><p>{{$rule[1]}}</p></div>@endforeach
    </section>
    @endforeach
  </div><div class="card-footer guide-actions"><button class="btn btn-light" type="button" id="guide-previous" disabled><i class="fas fa-arrow-left" aria-hidden="true"></i> წინა თემა</button><button class="btn btn-outline-primary" type="button" id="guide-next">შემდეგი თემა <i class="fas fa-arrow-right" aria-hidden="true"></i></button></div></article>
</section>
@endsection

@push('scripts')
<script nonce="{{ $cspNonce }}">
(function(){
  var panels=[].slice.call(document.querySelectorAll('.guide-panel'));
  var picker=document.getElementById('guide-topic');
  var search=document.getElementById('guide-search');
  var empty=document.getElementById('guide-no-results');
  var progress=document.getElementById('guide-progress');
  var previous=document.getElementById('guide-previous');
  var next=document.getElementById('guide-next');
  function activate(id,updateHash){
    var index=panels.findIndex(function(panel){return panel.id===id});
    if(index<0)return;
    panels.forEach(function(panel){panel.classList.toggle('is-active',panel.id===id)});
    picker.value=id;
    progress.textContent='თემა '+(index+1)+' / '+panels.length;
    previous.disabled=index===0;
    next.disabled=index===panels.length-1;
    if(updateHash)history.replaceState(null,'','#'+id);
  }
  picker.addEventListener('change',function(){activate(picker.value,true)});
  previous.addEventListener('click',function(){var index=panels.findIndex(function(panel){return panel.classList.contains('is-active')});if(index>0)activate(panels[index-1].id,true)});
  next.addEventListener('click',function(){var index=panels.findIndex(function(panel){return panel.classList.contains('is-active')});if(index<panels.length-1)activate(panels[index+1].id,true)});
  search.addEventListener('input',function(){
    var term=search.value.trim().toLocaleLowerCase('ka'),first=null,count=0;
    [].slice.call(picker.options).forEach(function(option){
      var panel=document.getElementById(option.value);
      var match=!term||panel.dataset.search.toLocaleLowerCase('ka').indexOf(term)!==-1;
      option.hidden=!match;
      if(match){count++;if(!first)first=panel.id}
    });
    empty.hidden=count!==0;
    if(term&&first)activate(first,false);
  });
  window.addEventListener('hashchange',function(){activate(location.hash.slice(1),false)});
  if(location.hash)activate(location.hash.slice(1),false);
}());
</script>
@endpush
